87	#[serde(rename_all = "camelCase")]
88	pub(crate) struct TypeInfo {
89	    pub id: u64,
90	    pub flags: u64,
91	    #[serde(default)]
92	    pub object_flags: u64,
93	    #[serde(default)]
94	    pub value: Option<Value>,
95	    #[serde(default)]
96	    pub is_tuple_type: bool,
97	    /// The checker's name for an intrinsic type (`"any"`, `"string"`, `"error"`). It alone tells a written `any` from
98	    /// the error type of an unresolved name: both carry the `Any` flag, and the error type has an id per site.
99	    #[serde(default)]
100	    pub intrinsic_name: Option<String>,
101	    /// `TupleElementFlags` of a tuple type's elements: required 1, optional 2, rest 4, variadic 8.
102	    #[serde(default)]
103	    pub element_flags: Vec<u64>,
104	    /// A tuple type written `readonly [...]`.
105	    #[serde(default)]
106	    pub readonly: bool,
107	    /// One declaration handle per element of a tuple whose elements are labeled, `[head: string]`; empty otherwise.
108	    #[serde(default)]
109	    pub labeled_element_declarations: Vec<String>,
110	    /// The text pieces of a template literal type, around its holes.
111	    #[serde(default)]
112	    pub texts: Vec<String>,
113	    /// The `this` type of a class or interface, which the checker also appends to a reference's type arguments.
114	    #[serde(default)]
115	    pub is_this_type: bool,
116	    /// The symbol that declares an object type; absent for primitives and unions.
117	    #[serde(default)]
118	    pub symbol: Option<CompactSymbol>,
119	    /// The alias this type was written through, `Size` in `type Size = "sm" | "lg"`.
120	    #[serde(default)]
121	    pub alias_symbol: Option<CompactSymbol>,
122	    /// Ids of the alias's type arguments; `Rpc::alias_type_arguments` fetches them.
123	    #[serde(default)]
124	    pub alias_type_arguments: Vec<u64>,
125	}
