256	/// One `tsc --api` session bound to a snapshot and project.
257	pub(crate) struct Rpc {
258	    client: Client,
259	    deadline: Duration,
260	    snapshot: u64,
261	    project: String,
262	    /// The compiler options the program was built with, for a snapshot that adds files to it ([`Rpc::layered`]).
263	    options: Value,
264	    /// Every call and its answer, when the caller asked to record a replay fixture; shared with a layered snapshot.
265	    recording: Option<Arc<Mutex<Vec<Value>>>>,
266	    calls: Arc<Mutex<BTreeMap<String, u64>>>,
267	}
