269	/// A diagnostic the checker reports for a file: where it starts and what it says.
270	#[derive(Debug, Clone, Deserialize)]
271	#[serde(rename_all = "camelCase")]
272	pub(crate) struct FileDiagnostic {
273	    /// The file the error is in, which is not always the file asked about.
274	    pub file_name: String,
275	    pub start_position: Position,
276	    /// `DiagnosticCategory`: warning 0, error 1, suggestion 2, message 3.
277	    pub category: u8,
278	    /// The message; a chain of messages arrives as an object, of which only the first is shown.
279	    pub text: Value,
280	}
281	
282	impl FileDiagnostic {
283	    pub(crate) fn is_error(&self) -> bool {
284	        self.category == 1
285	    }
286	
287	    pub(crate) fn message(&self) -> String {
288	        match &self.text {
289	            Value::String(text) => text.clone(),
290	            other => other.get("messageText").and_then(Value::as_str).unwrap_or("a type error").to_string(),
291	        }
292	    }
293	}
