509	    pub(crate) async fn type_parameters(&self, signature: u64) -> Result<Vec<TypeInfo>, CallError> {
510	        self.scoped("getTypeParametersOfSignature", json!({ "objectId": signature })).await
511	    }
512	
513	    /// The type a type parameter defaults to (`"div"` in `E extends ElementType = "div"`); none when it declares none.
514	    pub(crate) async fn default_of_type_parameter(&self, type_id: u64) -> Result<Option<TypeInfo>, CallError> {
515	        self.scoped("getDefaultFromTypeParameter", json!({ "objectId": type_id })).await
516	    }
