518	    /// The type a type alias or interface declares, `T` in `type A = T`.
519	    pub(crate) async fn declared_type_of_symbol(&self, symbol: &Value) -> Result<TypeInfo, CallError> {
520	        self.scoped("getDeclaredTypeOfSymbol", json!({ "symbol": symbol })).await
521	    }
522	
523	    /// The type errors in a file of the program.
524	    pub(crate) async fn semantic_diagnostics(&self, file: &str) -> Result<Vec<FileDiagnostic>, CallError> {
525	        self.scoped("getSemanticDiagnostics", json!({ "file": file })).await
526	    }
527	
528	    /// The symbol that declares a type: the interface, class, enum member or unique symbol behind it.
529	    pub(crate) async fn symbol_of_type(&self, type_id: u64) -> Result<Option<SymbolInfo>, CallError> {
530	        self.scoped("getSymbolOfType", json!({ "objectId": type_id })).await
531	    }
532	
533	    /// The types a class or interface extends, instantiated as it names them (`Omit<HTMLAttributes<HTMLDivElement>, "color">`);
534	    /// none for a type that is not a class or interface.
535	    pub(crate) async fn base_types(&self, type_id: u64) -> Result<Vec<TypeInfo>, CallError> {
536	        let bases: Option<Vec<TypeInfo>> = self.scoped("getBaseTypes", json!({ "type": type_id })).await?;
537	        Ok(bases.unwrap_or_default())
538	    }
539	
540	    pub(crate) async fn alias_type_arguments(&self, type_id: u64) -> Result<Vec<TypeInfo>, CallError> {
541	        self.scoped("getAliasTypeArgumentsOfType", json!({ "objectId": type_id })).await
542	    }
543	
544	    /// The generic type a reference instantiates; for a tuple reference, the tuple type that holds its element flags.
545	    pub(crate) async fn target_of_type(&self, type_id: u64) -> Result<TypeInfo, CallError> {
546	        self.scoped("getTargetOfType", json!({ "objectId": type_id })).await
547	    }
548	
549	    pub(crate) async fn parent_of_symbol(&self, symbol: &Value) -> Result<Option<SymbolInfo>, CallError> {
550	        self.scoped("getParentOfSymbolForChecker", json!({ "symbol": symbol })).await
551	    }
552	
553	    /// Whether each property is declared `readonly`, in one round trip.
554	    pub(crate) async fn readonly_symbols(&self, symbols: &[&Value]) -> Result<Vec<bool>, CallError> {
555	        let requests = symbols.iter().map(|symbol| ("isReadonlySymbol", json!({ "symbol": symbol }))).collect();
556	        self.batch(requests).await?.iter().map(|answer| decode(answer)).collect()
557	    }
558	
559	    /// Several requests in one round trip. A request the checker rejects fails the batch: nothing here asks for one
560	    /// that may legitimately fail.
561	    pub(crate) async fn batch(&self, requests: Vec<(&str, Value)>) -> Result<Vec<Box<RawValue>>, CallError> {
562	        let wanted = requests.len();
563	        let scoped: Vec<Value> = requests
564	            .into_iter()
565	            .map(|(method, mut params)| {
566	                if let Value::Object(map) = &mut params {
567	                    map.insert("snapshot".to_string(), json!(self.snapshot));
568	                    map.insert("project".to_string(), json!(self.project));
569	                }
570	                json!({ "method": method, "params": params })
571	            })
572	            .collect();
573	        let mut answers = Vec::with_capacity(wanted);
574	        let mut token: Option<String> = None;
575	        loop {
576	            let mut params = json!({ "requests": scoped });
577	            if let (Some(token), Some(map)) = (&token, params.as_object_mut()) {
578	                map.insert("continuationToken".to_string(), json!(token));
579	            }
580	            let page: BatchPage = decode(&self.call("batchRequests", params).await?)?;
581	            for response in page.responses {
582	                if let Some(error) = response.error {
583	                    return Err(CallError::Rejected(error));
584	                }
585	                answers.push(response.result.unwrap_or_else(|| RawValue::NULL.to_owned()));
586	            }
587	            match page.continuation_token {
588	                Some(next) => token = Some(next),
589	                None => break,
590	            }
591	        }
592	        if answers.len() != wanted {
593	            return Err(CallError::Rejected(format!("a batch of {wanted} requests got {} answers", answers.len())));
594	        }
595	        Ok(answers)
596	    }
597	
598	    pub(crate) async fn parameters(&self, signature: u64) -> Result<Vec<SymbolInfo>, CallError> {
599	        self.scoped("getParametersOfSignature", json!({ "objectId": signature })).await
600	    }
601	
602	    pub(crate) async fn return_type(&self, signature: u64) -> Result<TypeInfo, CallError> {
603	        self.scoped("getReturnTypeOfSignature", json!({ "objectId": signature })).await
604	    }
605	
606	    pub(crate) async fn properties(&self, type_id: u64) -> Result<Vec<SymbolInfo>, CallError> {
607	        self.scoped("getPropertiesOfType", json!({ "type": type_id })).await
608	    }
609	
610	    /// The members of a union, intersection or template literal, as the text the checker answered (a list of types).
611	    pub(crate) async fn members_text(&self, type_id: u64) -> Result<Box<RawValue>, CallError> {
612	        self.scoped_text("getTypesOfType", json!({ "objectId": type_id })).await
613	    }
614	
615	    /// The type arguments of a reference, as the text the checker answered (a list of types).
616	    pub(crate) async fn type_arguments_text(&self, type_id: u64) -> Result<Box<RawValue>, CallError> {
617	        self.scoped_text("getTypeArguments", json!({ "type": type_id })).await
618	    }
619	
620	    /// The call and construct signatures, the properties and the index signatures of a type, in one round trip.
621	    pub(crate) async fn object_members(&self, type_id: u64) -> Result<ObjectMembers, CallError> {
622	        let requests = vec![
623	            ("getSignaturesOfType", json!({ "type": type_id, "kind": SignatureKind::Call as u8 })),
624	            ("getSignaturesOfType", json!({ "type": type_id, "kind": SignatureKind::Construct as u8 })),
625	            ("getPropertiesOfType", json!({ "type": type_id })),
626	            ("getIndexInfosOfType", json!({ "type": type_id })),
627	        ];
628	        let mut answers = self.batch(requests).await?.into_iter();
629	        let mut next = || answers.next().ok_or_else(|| CallError::Rejected("a short batch".to_string()));
630	        Ok(ObjectMembers {
631	            calls: decode(&next()?)?,
632	            constructs: decode(&next()?)?,
633	            properties: decode(&next()?)?,
634	            indexes: decode(&next()?)?,
635	        })
636	    }
637	
638	    pub(crate) async fn alias_symbol(&self, type_id: u64) -> Result<Option<SymbolInfo>, CallError> {
639	        self.scoped("getAliasSymbolOfType", json!({ "objectId": type_id })).await
640	    }
641	
642	    pub(crate) async fn type_to_string(&self, type_id: u64) -> Result<String, CallError> {
643	        self.scoped("typeToString", json!({ "type": type_id })).await
644	    }
645	
646	    /// The type as written inside a type alias declaration, and never cut short: an alias at the top is printed as what
647	    /// it stands for (`(value?: string) => void`, not `Handler`), and a long type is printed to its end.
648	    pub(crate) async fn type_to_string_expanded(&self, type_id: u64) -> Result<String, CallError> {
649	        self.scoped("typeToString", json!({ "type": type_id, "flags": flag::PRINT_EXPANDED })).await
650	    }
651	}
652	
653	fn default_options() -> Value {
654	    // Numeric enum values: JSX preserve, ESNext modules, bundler resolution, ES2022.
655	    json!({ "jsx": 1, "module": 99, "moduleResolution": 100, "target": 9, "strict": true, "skipLibCheck": true, "noEmit": true })
656	}
657	
658	/// An answer parsed from its text straight into `T`, in one pass.
659	pub(crate) fn decode<T: DeserializeOwned>(answer: &RawValue) -> Result<T, CallError> {
660	    serde_json::from_str(answer.get())
661	        .map_err(|error| CallError::Rejected(format!("unexpected response shape: {error}")))
662	}
663	
664	#[cfg(test)]
665	mod tests {
666	    use super::*;
667	
668	    #[test]
669	    fn a_name_with_three_or_more_leading_underscores_loses_the_one_the_checker_added() {
670	        assert_eq!(unescape_leading_underscores("___size"), "__size");
671	        assert_eq!(unescape_leading_underscores("____triple"), "___triple");
672	        assert_eq!(unescape_leading_underscores("___0"), "__0");
673	    }
674	
