683	    fn a_symbol_arrives_with_the_name_the_source_writes() {
684	        let symbol: SymbolInfo =
685	            serde_json::from_value(json!({ "reference": {}, "name": "___size", "flags": 0 })).unwrap();
686	
687	        assert_eq!(symbol.name, "__size");
688	    }
689	}
