[profile.dev]
debug = false

# Optimized correctness binaries without release LTO, keeping the debug assertions and overflow checks that local
# `cargo test` runs; build times measured in notes/dev-loop-build.md.
[profile.ci]
inherits = "release"
lto = "off"
codegen-units = 16
debug-assertions = true
overflow-checks = true

# Release binaries (.github/workflows/release.yml) build with this profile twice, for PGO: -Cprofile-generate,
# training run, -Cprofile-use (notes/perf-pgo.md), then BOLT on Linux. Instrumented builds override rustc's LTO to
# thin, keeping the Cargo profile identical for PGO symbol matching. tools/wasm/build.sh applies its target-specific
# size and panic settings to this profile through scoped environment overrides.
[profile.release]
opt-level = 3
lto = "fat"
codegen-units = 1
strip = "symbols" # set to `false` for debug information
debug = false # set to `true` for debug information
panic = "unwind"

[workspace.lints.rust]
non_upper_case_globals = "deny"
non_camel_case_types = "deny"
non_snake_case = "deny"
# Rust 1.99: forming raw pointers through intermediate references can strengthen aliasing assumptions accidentally.
raw_borrows_via_references = "warn"

[workspace.lints.clippy]
# Keep the baseline aligned with oxc-project/oxc. Deny every enabled Clippy lint directly.
all = { level = "deny", priority = -2 }
pedantic = { level = "deny", priority = -1 }
complexity = { level = "deny", priority = -1 }
nursery = { level = "deny", priority = -1 }

