//! A logging stand-in for `tsrs`: spawns `$REAL_TSRS` with the same arguments and forwards Content-Length framed
//! JSON-RPC both ways, appending every frame to `$PROXY_LOG` as `C2S|S2C <micros> <body>`.
use std::io::{BufRead, BufReader, Read, Write};
use std::process::{Command, Stdio};
use std::sync::{Arc, Mutex};
use std::time::Instant;

fn read_frame(reader: &mut impl BufRead) -> Option<Vec<u8>> {
    let mut length = None;
    loop {
        let mut line = String::new();
        if reader.read_line(&mut line).ok()? == 0 {
            return None;
        }
        let line = line.trim_end();
        if line.is_empty() {
            break;
        }
        if let Some(value) = line.strip_prefix("Content-Length:") {
            length = value.trim().parse::<usize>().ok();
        }
    }
    let mut body = vec![0; length?];
    reader.read_exact(&mut body).ok()?;
    Some(body)
}

fn write_frame(writer: &mut impl Write, body: &[u8]) -> std::io::Result<()> {
    write!(writer, "Content-Length: {}\r\n\r\n", body.len())?;
    writer.write_all(body)?;
    writer.flush()
}

fn main() {
    let real = std::env::var("REAL_TSRS").expect("REAL_TSRS");
    let log_path = std::env::var("PROXY_LOG").expect("PROXY_LOG");
    let args: Vec<String> = std::env::args().skip(1).collect();
    let log = Arc::new(Mutex::new(std::fs::File::create(&log_path).unwrap()));
