fn segments(calls: &[Call], stamps: &[f64]) -> Timing {
    // stamps[i] is the time at which answer i arrived, stamps[0] the start; the first createSnapshot splits setup.
    let snap = calls.iter().position(|c| c.method == "createSnapshot").unwrap();
    Timing {
        setup_ms: stamps[snap],
        snapshot_ms: stamps[snap + 1] - stamps[snap],
        queries_ms: stamps[calls.len()] - stamps[snap + 1],
        queries: calls.len() - snap - 1,
    }
}

fn replay_inproc(session: &Session, calls: &[Call], remap: bool) -> (Vec<Result<String, String>>, Vec<f64>) {
    let mut snapshots = std::collections::HashMap::<u64, u64>::new();
    let mut answers = Vec::with_capacity(calls.len());
    let mut stamps = Vec::with_capacity(calls.len() + 1);
    let start = Instant::now();
    stamps.push(0.0);
    for call in calls {
        let params = if remap && !snapshots.is_empty() {
            let mut params = call.params.clone();
            remap_snapshots(&mut params, &snapshots);
            serde_json::to_string(&params).unwrap()
        } else {
            call.params_text.clone()
        };
        let answer = match session.handle_request(&call.method, params.as_bytes()) {
            Ok(Response::Json(text)) => Ok(text),
            Ok(Response::Binary(_)) => Err("binary".to_string()),
            Err(error) => Err(error.to_string()),
        };
        if remap && matches!(call.method.as_str(), "createSnapshot" | "updateSnapshot") {
            if let (Ok(text), Some(recorded)) = (&answer, call.result.as_ref()) {
                let actual: Value = serde_json::from_str(text).unwrap();
                snapshots.insert(recorded["snapshot"].as_u64().unwrap(), actual["snapshot"].as_u64().unwrap());
            }
        }
        answers.push(answer);
        stamps.push(start.elapsed().as_secs_f64() * 1000.0);
    }
    (answers, stamps)
}

fn remap_snapshots(value: &mut Value, map: &std::collections::HashMap<u64, u64>) {
    match value {
        Value::Object(object) => {
            for (key, inner) in object.iter_mut() {
                if key == "snapshot" {
                    if let Some(to) = inner.as_u64().and_then(|from| map.get(&from)) {
                        *inner = json!(to);
                    }
                } else {
                    remap_snapshots(inner, map);
                }
            }
        }
        Value::Array(items) => items.iter_mut().for_each(|item| remap_snapshots(item, map)),
        _ => {}
    }
}

fn on_big_stack<T: Send + 'static>(mib: usize, f: impl FnOnce() -> T + Send + 'static) -> T {
    std::thread::Builder::new().stack_size(mib << 20).spawn(f).unwrap().join().unwrap()
}

fn inproc(path: &str) {
    let (cwd, calls) = load(path);
    let (u0, s0, _) = rusage(libc::RUSAGE_SELF);
    let wall = Instant::now();
    let (answers, stamps, session_ms) = on_big_stack(512, move || {
        let began = Instant::now();
        let session = new_session(&cwd);
        let session_ms = began.elapsed().as_secs_f64() * 1000.0;
        let (answers, stamps) = replay_inproc(&session, &calls, false);
        session.close();
        (answers, stamps, session_ms)
    });
    let wall_ms = wall.elapsed().as_secs_f64() * 1000.0;
    let (u1, s1, maxrss) = rusage(libc::RUSAGE_SELF);
    let (_, calls) = load(path);
    let t = segments(&calls, &stamps);
    let (differ, first) = compare(&calls, &answers);
    println!(
        "{}",
        json!({ "mode": "inproc", "requests": calls.len(), "sessionMs": session_ms, "setupMs": t.setup_ms,
            "snapshotMs": t.snapshot_ms, "queriesMs": t.queries_ms, "queries": t.queries,
            "answerMs": t.snapshot_ms + t.queries_ms, "wallMs": wall_ms, "cpuMs": (u1 - u0) + (s1 - s0),
            "peakRssMiB": maxrss as f64 / 1048576.0, "differ": differ, "firstDiffer": first })
    );
}

fn read_frame(reader: &mut impl BufRead) -> Option<Vec<u8>> {
    let mut length = None;
    loop {
        let mut line = String::new();
        if reader.read_line(&mut line).ok()? == 0 {
            return None;
        }
        let line = line.trim_end();
        if line.is_empty() {
            break;
        }
        if let Some(value) = line.strip_prefix("Content-Length:") {
            length = value.trim().parse::<usize>().ok();
        }
    }
    let mut body = vec![0; length?];
    reader.read_exact(&mut body).ok()?;
    Some(body)
}

fn pipe(binary: &str, path: &str) {
    let (cwd, calls) = load(path);
    let wall = Instant::now();
    let mut child = Command::new(binary)
        .args(["--api", "--async", "--cwd", &cwd])
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::null())
        .spawn()
        .unwrap();
    let mut input = child.stdin.take().unwrap();
    let mut output = BufReader::new(child.stdout.take().unwrap());
    let mut answers = Vec::with_capacity(calls.len());
    let mut stamps = Vec::with_capacity(calls.len() + 1);
    let start = Instant::now();
    stamps.push(0.0);
    for call in &calls {
        write!(input, "Content-Length: {}\r\n\r\n", call.body.len()).unwrap();
        input.write_all(call.body.as_bytes()).unwrap();
        input.flush().unwrap();
        let id = serde_json::from_str::<Value>(&call.body).unwrap()["id"].clone();
        loop {
            let frame = read_frame(&mut output).unwrap();
            let message: Value = serde_json::from_slice(&frame).unwrap();
            if message.get("id") == Some(&id) {
                answers.push(match message.get("error") {
                    Some(error) => Err(error.to_string()),
                    None => Ok(message["result"].to_string()),
                });
                break;
            }
        }
        stamps.push(start.elapsed().as_secs_f64() * 1000.0);
    }
    drop(input);
    child.wait().unwrap();
    let wall_ms = wall.elapsed().as_secs_f64() * 1000.0;
    let (u, s, maxrss) = rusage(libc::RUSAGE_CHILDREN);
    let (us, ss, _) = rusage(libc::RUSAGE_SELF);
    let t = segments(&calls, &stamps);
    let (differ, first) = compare(&calls, &answers);
    println!(
        "{}",
        json!({ "mode": "pipe", "binary": binary, "requests": calls.len(), "setupMs": t.setup_ms,
            "snapshotMs": t.snapshot_ms, "queriesMs": t.queries_ms, "queries": t.queries,
            "answerMs": t.snapshot_ms + t.queries_ms, "wallMs": wall_ms, "childCpuMs": u + s, "clientCpuMs": us + ss,
            "childPeakRssMiB": maxrss as f64 / 1048576.0, "differ": differ, "firstDiffer": first })
    );
}

fn cycles(path: &str, n: usize) {
    let (cwd, _) = load(path);
    let path = path.to_string();
    println!("{}", json!({ "cycle": 0, "rssMiB": rss_mib() }));
    for cycle in 1..=n {
        let (cwd, path) = (cwd.clone(), path.clone());
        let (differ, ms) = on_big_stack(512, move || {
            let (_, calls) = load(&path);
            let began = Instant::now();
            let session = new_session(&cwd);
            let (answers, _) = replay_inproc(&session, &calls, true);
            session.close();
            drop(session);
            let ms = began.elapsed().as_secs_f64() * 1000.0;
            (compare(&calls, &answers).0, ms)
        });
        println!("{}", json!({ "cycle": cycle, "rssMiB": rss_mib(), "differ": differ, "ms": ms }));
    }
}

/// A file whose type nests `depth` levels (`{ a: { a: ... string ... } }`), checked through createSnapshot with an
/// in-memory layer and getSemanticDiagnostics, on a thread with `stack_mib` of stack.
fn deep(depth: usize, stack_mib: usize, file: &str) {
    let mut text = String::from("export type Deep = ");
    for _ in 0..depth {
        text.push_str("{ a: ");
    }
    text.push_str("string");
    for _ in 0..depth {
        text.push_str(" }");
    }
    text.push_str(";\nexport const value: Deep = null as any;\nexport const s: string = value");
    for _ in 0..depth {
        text.push_str(".a");
    }
    text.push_str(";\n");
    let file = file.to_string();
    let outcome = on_big_stack(stack_mib, move || {
        let session = new_session("/");
        let options = json!({ "strict": true, "noEmit": true, "target": 9, "module": 99, "moduleResolution": 100 });
        let params = json!({
            "fileSystem": { "kind": "layer", "files": { file.clone(): text } },
            "createPrograms": [{ "rootFiles": [file.clone()], "compilerOptions": options }],
        });
        let began = Instant::now();
        let created = session.handle_request("createSnapshot", params.to_string().as_bytes());
        let Ok(Response::Json(created)) = created else { return format!("createSnapshot failed: {created:?}") };
        let created: Value = serde_json::from_str(&created).unwrap();
        let params = json!({ "snapshot": created["snapshot"], "project": created["projects"][0]["id"], "file": file });
        let diagnostics = session.handle_request("getSemanticDiagnostics", params.to_string().as_bytes());
        let summary = match diagnostics {
            Ok(Response::Json(text)) => format!("ok, {} bytes of diagnostics", text.len()),
            other => format!("{other:?}").chars().take(300).collect(),
        };
        format!("{summary} in {:?}", began.elapsed())
    });
    println!("{}", json!({ "mode": "deep", "depth": depth, "stackMiB": stack_mib, "outcome": outcome }));
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    match args.get(1).map(String::as_str) {
        Some("prepare") => prepare(&args[2], &args[3]),
        Some("inproc") => inproc(&args[2]),
        Some("pipe") => pipe(&args[2], &args[3]),
        Some("cycles") => cycles(&args[2], args[3].parse().unwrap()),
        Some("deep") => deep(args[2].parse().unwrap(), args[3].parse().unwrap(), &args[4]),
        _ => eprintln!("usage: spike prepare|inproc|pipe|cycles|deep ..."),
    }
}

