import json
import statistics
import sys

rows = {}
for line in open(sys.argv[1]):
    side, text = line.split(" ", 1)
    rows.setdefault(side, []).append(json.loads(text))

def show(side, key):
    values = [r[key] for r in rows.get(side, []) if key in r]
    if values:
        print(f"{side:8} {key:16} median {statistics.median(values):8.1f}  range {min(values):8.1f} .. {max(values):8.1f}  n={len(values)}")

for side in ("inproc", "pipe23", "pipe24"):
    for key in ("answerMs", "snapshotMs", "queriesMs", "setupMs", "wallMs", "cpuMs", "childCpuMs", "clientCpuMs", "peakRssMiB", "childPeakRssMiB", "differ", "requests"):
        show(side, key)
for key in ("firstAnswerMs", "startMs", "structuralMs", "answeredByChecker"):
    show("harness", key)

